// Asia/Kolkata is UTC+05:30 (no DST). Compute "yesterday" in IST independent of server TZ.
const IST_OFFSET_MS = (5 * 60 + 30) * 60 * 1000;
const nowUtcMs = Date.now();
const istNow = new Date(nowUtcMs + IST_OFFSET_MS);
const istYesterday = new Date(istNow.getTime() - 24 * 60 * 60 * 1000);
const yyyy = istYesterday.getUTCFullYear();
const mm = String(istYesterday.getUTCMonth() + 1).padStart(2, '0');
const dd = String(istYesterday.getUTCDate()).padStart(2, '0');
const target_date = yyyy + '-' + mm + '-' + dd;
const run_id = 'run_' + $execution.id + '_' + target_date;
return [{ json: { run_id: run_id, target_date: target_date, timezone: 'Asia/Kolkata' } }];

const results = $('Collect Results').all().map(function (i) { return i.json; });
const ctx = $('Compute Run Context').first().json;

const logRows = results.map(function (r) {
  return {
    run_id: r.run_id,
    timestamp: r.collected_at || new Date().toISOString(),
    workflow: 'Daily Social Metrics Orchestrator',
    account_id: r.account_id,
    platform: r.platform,
    operation: r.operation || 'daily_metrics',
    status: r.data_status,
    http_status: r.http_status == null ? '' : r.http_status,
    execution_id: $execution.id,
    retry_count: '',
    error_message: r.error_message || '',
    duration_ms: '',
  };
});

return [{
  json: {
    run_id: ctx.run_id,
    target_date: ctx.target_date,
    records_written: results.length,
    api_requests: results.length,
    log_payload: JSON.stringify(logRows),
    summary_payload: JSON.stringify({ results: results, records_written: results.length, api_requests: results.length }),
  },
}];
